import numpy as np
from PIL import Image
from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['right']);M=np.array(o.meta['cameras']['right']['cam2world_gl']);K=np.array(o.meta['cameras']['right']['intrinsic_cv']);
for l in ['initial','push_up_probe','lift_center']:
 im=np.array(Image.open('/app/output/'+l+'_right.png'));d=np.load('/app/output/'+l+'_right_depth.npy')[0].astype(float);print('\n',l)
 for u in [161,164,166,170,180,185,188]:
  vals=[]
  for v in range(68,116):
   R,G,B=im[v,u];
   if R>70 and R>G*1.4 and R>B*1.4:
    dep=d[v,u];cg=np.array([(u-160)*dep/K[0,0],-(v-120)*dep/K[1,1],-dep,1]);p=(M@cg)[:3]
    if -.2<p[0]<-.05 and .55<p[1]<.85 and 0<p[2]<.3: vals.append((v,round(p[0],3),round(p[1],3),round(p[2],3)))
  print('u',u,vals)
